        if h is None:
            val = "-"
        else:
            h_idx = h.year * 12 + h.month
            if h_idx <= mat_idx and (mat_idx - h_idx) % period == 0:
                val = principal + interest if h_idx == mat_idx else interest
            else:
                val = "-"

        if isinstance(val, float) and val.is_integer():
            val = int(val)
        ws.cell(row=r, column=c).value = val

# Center-align the graded range while leaving number formats untouched.
