                vertical=old.vertical,
                wrap_text=old.wrap_text,
                text_rotation=old.text_rotation,
                indent=old.indent,
                shrink_to_fit=old.shrink_to_fit,
            )
        except Exception:
            pass

# Center-align row 5 as well if it was filled.
for c in range(start_col, end_col + 1):
    try:
        cell = ws.cell(row=5, column=c)
        old = cell.alignment if cell.alignment is not None else Alignment()
        cell.alignment = Alignment(
            horizontal="center",
            vertical=old.vertical,
            wrap_text=old.wrap_text,
            text_rotation=old.text_rotation,
            indent=old.indent,
            shrink_to_fit=old.shrink_to_fit,
        )
    except Exception:
        pass

print("filled", (end_row - start_row + 1) * (end_col - start_col + 1), "cells")
print("E6", ws.cell(row=6, column=5).value)
print("L6", ws.cell(row=6, column=12).value)
print("X6", ws.cell(row=6, column=24).value)
print("V17", ws.cell(row=17, column=22).value)

wb.save(OUT)
